import { Agenda } from '@refy-design/web';
import type { ComponentProps } from 'react';
export function Example() {
  const args: Pick<
    ComponentProps<typeof Agenda>,
    'events' | 'title' | 'label' | 'from' | 'to' | 'timezone' | 'emptyMessage'
  > = {
    events: [],
    title: 'Conference week',
    label: 'Conference schedule',
    from: undefined,
    to: undefined,
    timezone: 'America/Sao_Paulo',
